import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fixed, fixedPad, display, hex8 } from '../../src/util/rustfmt.js';

const view = new DataView(new ArrayBuffer(8));
const f64 = (bits) => {
  view.setBigUint64(0, BigInt('0x' + bits));
  return view.getFloat64(0);
};

test('fixed, fixedPad and display match Rust', () => {
  let n = 0;
  for (const [bits, p0, p1, p2, p3, p17, w4, w8, w1, disp] of TABLE) {
    const x = f64(bits);
    assert.equal(fixed(x, 0), p0, bits + ' {:.0}');
    assert.equal(fixed(x, 1), p1, bits + ' {:.1}');
    assert.equal(fixed(x, 2), p2, bits + ' {:.2}');
    assert.equal(fixed(x, 3), p3, bits + ' {:.3}');
    assert.equal(fixed(x, 17), p17, bits + ' {:.17}');
    assert.equal(fixedPad(x, 4, 1), w4, bits + ' {:04.1}');
    assert.equal(fixedPad(x, 8, 3), w8, bits + ' {:08.3}');
    assert.equal(fixedPad(x, 1, 0), w1, bits + ' {:01.0}');
    assert.equal(display(x), disp, bits + ' {}');
    n++;
  }
  assert.equal(n, TABLE.length);
});

test('the ties and edges spelled out', () => {
  assert.deepEqual([0.5, 1.5, 2.5, -0.5].map((x) => fixed(x, 0)), ['0', '2', '2', '-0']);
  assert.equal(fixed(0.125, 2), '0.12');
  assert.equal(fixed(-0, 1), '-0.0');
  assert.equal(display(1e21), '1000000000000000000000');
  assert.equal(display(1.5e-7), '0.00000015');
  assert.equal(display(-0), '-0');
  assert.equal(display(1), '1');
  assert.equal(fixedPad(NaN, 4, 1), '0NaN');
  assert.equal(fixed(-Infinity, 1), '-inf');
});

test('hex8 matches Rust', () => {
  for (const [n, s] of HEX) assert.equal(hex8(n), s);
});

